/* core/data.js: the course's market data.
 *
 * Built-in data is generated by course/build.py from data/live-2026-10-18/ (real Phoenix,
 * Kraken and Coinbase books fetched 2026-10-18 04:31 UTC) and inlined into the page as
 * <script type="application/json" id="obz-data">, which is parsed, never executed.
 * Readers can also paste or upload their own export (format v1 or v2, PLAN.md §3.4).
 *
 *   OBZ.data.active()              the dataset every widget should show (normalized, below)
 *   OBZ.data.subscribe(fn)         fn(dataset) whenever the active dataset changes -> unsubscribe
 *   OBZ.data.venue("kraken")       one normalized venue of the active dataset (or null)
 *   OBZ.data.snapshot("phoenix")   an OBZ.engine.Snapshot (exact ticks/lots when available)
 *   OBZ.data.book("phoenix")       a FRESH OBZ.engine.OrderBook loaded from that snapshot
 *   OBZ.data.phoenix()             the full raw Phoenix snapshot summary (slot, fee, junk quotes)
 *   OBZ.data.parse(text, source)   -> {ok: true, dataset} | {ok: false, error, path}
 *   OBZ.data.readFile(file)        -> Promise of the same
 *   OBZ.data.use(dataset) / reset()
 *   OBZ.data.label(venue) "Phoenix", OBZ.data.colorVar(venue) "--phoenix"
 *
 * Normalized dataset:
 *   {kind, version, generatedAt, source: "builtin"|"paste"|"file", label,
 *    venues: [{venue, label, symbol, fetchedAt, mid, spreadBps, bids: [[usd, sol]], asks,
 *              curve: {buy: [[usd, bps|null, full]], sell}, meta, feeBps, feeSource, depthUsd}],
 *    ammUsdReserve, jupiter: [], timeseries: null|{...}, phoenixAccount: null|{...}}
 */
(function (OBZ) {
  "use strict";

  const MAX_BYTES = 5 * 1024 * 1024;
  const MAX_LEVELS = 50000;
  const KIND = "impact-analyzer-export";
  const DEFAULT_FEES = { phoenix: 2, kraken: 40, coinbase: 120, jupiter: 0 }; // fees.py base tiers
  const LABELS = { phoenix: "Phoenix", kraken: "Kraken", coinbase: "Coinbase", amm: "x·y=k AMM", jupiter: "Jupiter", solfi: "SolFi" };
  const COLORS = { phoenix: "--phoenix", kraken: "--kraken", coinbase: "--coinbase", amm: "--amm", jupiter: "--amm", solfi: "--amm" };
  const FALLBACK_COLORS = ["--accent", "--phoenix", "--kraken", "--coinbase", "--amm"];

  // ---- built-in payload ------------------------------------------------------------
  let payload = null;
  function loadPayload() {
    if (payload) return payload;
    payload = { builtin: null, phoenix: null };
    try {
      const el = document.getElementById("obz-data");
      if (el && el.textContent.trim()) payload = JSON.parse(el.textContent);
    } catch (e) {
      console.error("OBZ: built-in data failed to parse", e);
    }
    return payload;
  }

  // ---- validation ------------------------------------------------------------------
  class DataError extends Error { constructor(path, msg) { super(msg); this.path = path; } }
  const isObj = (v) => v !== null && typeof v === "object" && !Array.isArray(v);
  const isNum = (v) => typeof v === "number" && isFinite(v);
  function need(cond, path, msg) { if (!cond) throw new DataError(path, `${path || "the file"} ${msg}`); }
  function optNum(v, path, { min = -Infinity, nullable = true } = {}) {
    if (v === undefined) return;
    if (v === null) { need(nullable, path, "must be a number, not null"); return; }
    need(isNum(v) && v >= min, path, min > -Infinity ? `must be a number ≥ ${min}` : "must be a number");
  }

  function validateLevels(arr, path, descending) {
    need(Array.isArray(arr), path, "must be a list of [price, size] pairs");
    need(arr.length <= MAX_LEVELS, path, `has ${arr.length} levels; the limit is ${MAX_LEVELS}`);
    for (let i = 0; i < arr.length; i++) {
      const lv = arr[i], p = `${path}[${i}]`;
      need(Array.isArray(lv) && lv.length >= 2, p, "must be a [price, size] pair");
      need(isNum(lv[0]) && lv[0] > 0, `${p}[0]`, "(the price) must be a positive number");
      need(isNum(lv[1]) && lv[1] > 0, `${p}[1]`, "(the size) must be a positive number");
      if (i > 0) {
        const ok = descending ? arr[i - 1][0] > lv[0] : arr[i - 1][0] < lv[0];
        need(ok, p, `is out of order: ${descending ? "bids must go from the highest price down" : "asks must go from the lowest price up"}`);
      }
    }
  }

  function validateVenue(v, path) {
    need(isObj(v), path, "must be an object");
    need(typeof v.venue === "string" && v.venue.length > 0 && v.venue.length <= 40, `${path}.venue`, "must be a short name like \"phoenix\"");
    if (v.symbol !== undefined) need(typeof v.symbol === "string" && v.symbol.length <= 40, `${path}.symbol`, "must be a short text label");
    optNum(v.fetched_at, `${path}.fetched_at`);
    validateLevels(v.bids, `${path}.bids`, true);
    validateLevels(v.asks, `${path}.asks`, false);
    need(v.bids.length > 0 || v.asks.length > 0, path, "has an empty book (no bids and no asks)");
    if (v.bids.length && v.asks.length) need(v.bids[0][0] < v.asks[0][0], `${path}.bids[0]`, "is crossed: the best bid must be below the best ask");
    optNum(v.mid, `${path}.mid`);
    optNum(v.spread_bps, `${path}.spread_bps`);
    optNum(v.fee_bps, `${path}.fee_bps`, { min: 0, nullable: false });
    if (v.meta !== undefined) need(isObj(v.meta), `${path}.meta`, "must be an object");
    if (v.curve !== undefined) {
      need(isObj(v.curve), `${path}.curve`, "must be an object with buy/sell lists");
      for (const side of ["buy", "sell"]) {
        const c = v.curve[side];
        if (c === undefined) continue;
        need(Array.isArray(c) && c.length <= 1000, `${path}.curve.${side}`, "must be a list of [usd, bps, filled] points");
        c.forEach((pt, i) => {
          const p = `${path}.curve.${side}[${i}]`;
          need(Array.isArray(pt) && pt.length >= 2 && isNum(pt[0]) && pt[0] > 0 && (pt[1] === null || isNum(pt[1])), p, "must be [usd, bps or null, filled]");
          if (pt.length > 2) need(typeof pt[2] === "boolean", `${p}[2]`, "must be true or false");
        });
      }
    }
    if (v.depth_usd !== undefined) {
      need(isObj(v.depth_usd), `${path}.depth_usd`, "must be an object like {\"0.01\": [bidUsd, askUsd]}");
      for (const k of Object.keys(v.depth_usd)) {
        const d = v.depth_usd[k];
        need(Array.isArray(d) && d.length === 2 && isNum(d[0]) && isNum(d[1]), `${path}.depth_usd["${k}"]`, "must be [bidUsd, askUsd]");
      }
    }
  }

  function validateTimeseries(ts, path) {
    need(isObj(ts), path, "must be an object");
    optNum(ts.interval_s, `${path}.interval_s`, { min: 1, nullable: false });
    need(Array.isArray(ts.t) && ts.t.length <= 200000 && ts.t.every(isNum), `${path}.t`, "must be a list of unix times");
    need(isObj(ts.series), `${path}.series`, "must be an object keyed by venue");
    const n = ts.t.length;
    const checkArr = (arr, p, item) => {
      need(Array.isArray(arr) && arr.length <= n, p, `must be a list no longer than t (${n})`);
      arr.forEach((x, i) => need(x === null || item(x), `${p}[${i}]`, "has the wrong type"));
    };
    for (const venue of Object.keys(ts.series)) {
      const s = ts.series[venue], p = `${path}.series.${venue}`;
      need(isObj(s), p, "must be an object of metric lists");
      for (const k of Object.keys(s)) {
        const val = s[k];
        if (Array.isArray(val)) checkArr(val, `${p}.${k}`, (x) => isNum(x) || (Array.isArray(x) && x.every((y) => y === null || isNum(y))));
        else if (isObj(val)) {
          // Either keyed by trade size ({"1000": [...]}, e.g. round_trip_bps, which has no
          // side) or by side, then size ({"buy": {"1000": [...]}}, e.g. cost_bps_vs_ref).
          for (const key of Object.keys(val)) {
            const inner = val[key];
            if (Array.isArray(inner)) { checkArr(inner, `${p}.${k}["${key}"]`, isNum); continue; }
            need(isObj(inner), `${p}.${k}.${key}`, "must be a list, or an object keyed by trade size");
            for (const size of Object.keys(inner)) checkArr(inner[size], `${p}.${k}.${key}["${size}"]`, isNum);
          }
        } else need(false, `${p}.${k}`, "must be a list or an object of lists");
      }
    }
  }

  function validatePhoenixAccount(pa, path) {
    need(isObj(pa), path, "must be an object");
    optNum(pa.slot, `${path}.slot`, { min: 0 });
    optNum(pa.offset, `${path}.offset`, { min: 0, nullable: false });
    need(typeof pa.hex === "string" && /^[0-9a-fA-F]*$/.test(pa.hex) && pa.hex.length % 2 === 0, `${path}.hex`, "must be a string of hex digits (two per byte)");
    need(Array.isArray(pa.fields) && pa.fields.length <= 5000, `${path}.fields`, "must be a list of field descriptions");
    pa.fields.forEach((f, i) => {
      const p = `${path}.fields[${i}]`;
      need(isObj(f), p, "must be an object");
      need(typeof f.name === "string" && f.name.length <= 80, `${p}.name`, "must be a short text name");
      need(Number.isInteger(f.offset) && f.offset >= 0, `${p}.offset`, "must be a whole number ≥ 0");
      need(Number.isInteger(f.size) && f.size >= 1 && f.size <= 4096, `${p}.size`, "must be a whole number of bytes (1–4096)");
      if (f.type !== undefined) need(typeof f.type === "string" && f.type.length <= 24, `${p}.type`, "must be a type name like \"u64\"");
      if (f.explain !== undefined) need(typeof f.explain === "string" && f.explain.length <= 2000, `${p}.explain`, "must be text");
      if (f.value !== undefined) need(f.value === null || ["number", "string", "boolean"].includes(typeof f.value), `${p}.value`, "must be a number, text or null");
    });
  }

  function validateJupiter(arr, path) {
    need(Array.isArray(arr) && arr.length <= 20000, path, "must be a list of quotes");
    arr.forEach((q, i) => {
      const p = `${path}[${i}]`;
      need(isObj(q), p, "must be an object");
      need(typeof q.dex === "string" && q.dex.length <= 60, `${p}.dex`, "must be a DEX name");
      need(q.side === "buy" || q.side === "sell", `${p}.side`, "must be \"buy\" or \"sell\"");
      need(isNum(q.usd) && q.usd > 0, `${p}.usd`, "must be a positive number");
      optNum(q.cost_bps_vs_ref, `${p}.cost_bps_vs_ref`);
      optNum(q.slot, `${p}.slot`, { min: 0 });
      // A leg is a pool name, or {label, input_mint?, output_mint?} when the export keeps the tokens each leg swaps.
      const legOk = (r) => (typeof r === "string" && r.length <= 60) || (isObj(r) && typeof r.label === "string" && r.label.length <= 60);
      if (q.route !== undefined) need(Array.isArray(q.route) && q.route.every(legOk), `${p}.route`, "must be a list of pool names");
    });
  }

  /** Throws DataError naming the bad field, or returns true. */
  function validate(d) {
    need(isObj(d), "", "must be a JSON object");
    need(d.kind === KIND, "kind", `must be "${KIND}". Is this the playground.json (or export) file from the analyzer?`);
    need(d.version === 1 || d.version === 2, "version", "must be 1 or 2");
    optNum(d.generated_at, "generated_at");
    need(Array.isArray(d.venues) && d.venues.length > 0 && d.venues.length <= 20, "venues", "must be a list of 1–20 venues");
    d.venues.forEach((v, i) => validateVenue(v, `venues[${i}]`));
    optNum(d.amm_usd_reserve, "amm_usd_reserve", { min: 0 });
    if (d.jupiter !== undefined) validateJupiter(d.jupiter, "jupiter");
    if (d.timeseries !== undefined && d.timeseries !== null) validateTimeseries(d.timeseries, "timeseries");
    if (d.phoenix_account !== undefined && d.phoenix_account !== null) validatePhoenixAccount(d.phoenix_account, "phoenix_account");
    return true;
  }

  // ---- normalization ---------------------------------------------------------------
  function normalize(d, source, extra) {
    const venues = d.venues.map((v) => {
      const fee = isNum(v.fee_bps) ? v.fee_bps
        : v.meta && isNum(v.meta.taker_fee_bps) ? v.meta.taker_fee_bps
          : DEFAULT_FEES[v.venue];
      return {
        venue: v.venue, label: label(v.venue), symbol: v.symbol || "", fetchedAt: v.fetched_at || 0,
        mid: isNum(v.mid) ? v.mid : (v.bids.length && v.asks.length ? (v.bids[0][0] + v.asks[0][0]) / 2 : null),
        spreadBps: isNum(v.spread_bps) ? v.spread_bps : null,
        bids: v.bids, asks: v.asks, curve: v.curve || { buy: [], sell: [] }, meta: v.meta || {},
        feeBps: fee === undefined ? null : fee,
        feeSource: isNum(v.fee_bps) ? "export" : v.meta && isNum(v.meta.taker_fee_bps) ? "account" : fee === undefined ? "unknown" : "base tier (fees.py)",
        depthUsd: v.depth_usd || null,
      };
    });
    // Label a dataset by when its books were fetched (not when the file was written).
    const fetched = venues.map((v) => v.fetchedAt).filter((t) => isNum(t) && t > 0);
    const t = fetched.length ? Math.min(...fetched) : d.generated_at;
    const when = t ? OBZ.util.fmt.date(t) : "";
    const lbl = source === "builtin" ? `Built-in snapshots${when ? " · fetched " + when : ""}` : `${source === "file" ? "Your file" : "Your pasted export"}${when ? " · fetched " + when : ""}`;
    return {
      kind: d.kind, version: d.version, generatedAt: d.generated_at || 0, source, label: lbl,
      venues, ammUsdReserve: isNum(d.amm_usd_reserve) ? d.amm_usd_reserve : null,
      jupiter: d.jupiter || [], timeseries: d.timeseries || null, phoenixAccount: d.phoenix_account || null,
      phoenixRaw: (extra && extra.phoenixRaw) || null,
    };
  }

  function parse(text, source = "paste") {
    if (typeof text !== "string") return { ok: false, path: "", error: "Nothing to load." };
    if (text.length > MAX_BYTES) return { ok: false, path: "", error: `That is ${(text.length / 1048576).toFixed(1)} MB; the limit is 5 MB. Export fewer venues or a shorter time range.` };
    if (!text.trim()) return { ok: false, path: "", error: "The text box is empty. Paste the contents of playground.json (or an export) first." };
    let d;
    try { d = JSON.parse(text); } catch (e) { return { ok: false, path: "", error: "That isn't valid JSON: " + e.message }; }
    try { validate(d); } catch (e) {
      if (e instanceof DataError) return { ok: false, path: e.path, error: e.message };
      return { ok: false, path: "", error: "Could not read that file: " + e.message };
    }
    return { ok: true, dataset: normalize(d, source) };
  }

  function readFile(file) {
    return new Promise((resolve) => {
      if (!file) { resolve({ ok: false, path: "", error: "No file chosen." }); return; }
      if (file.size > MAX_BYTES) { resolve({ ok: false, path: "", error: `That file is ${(file.size / 1048576).toFixed(1)} MB; the limit is 5 MB.` }); return; }
      const r = new FileReader();
      r.onload = () => resolve(parse(String(r.result), "file"));
      r.onerror = () => resolve({ ok: false, path: "", error: "The browser could not read that file." });
      r.readAsText(file);
    });
  }

  // ---- active dataset + subscriptions -------------------------------------------------
  let builtinDs = null, active = null;
  const subs = new Set();
  const snapCache = new Map();

  function builtin() {
    if (builtinDs) return builtinDs;
    const p = loadPayload();
    if (p && p.builtin) {
      try { validate(p.builtin); builtinDs = normalize(p.builtin, "builtin", { phoenixRaw: p.phoenix || null }); }
      catch (e) { console.error("OBZ: built-in data is invalid:", e.message); }
    }
    if (!builtinDs) builtinDs = { kind: KIND, version: 1, generatedAt: 0, source: "builtin", label: "No built-in data", venues: [], ammUsdReserve: null, jupiter: [], timeseries: null, phoenixAccount: null, phoenixRaw: null };
    return builtinDs;
  }
  function activeDs() { return active || builtin(); }
  function use(ds) { active = ds; snapCache.clear(); for (const fn of Array.from(subs)) { try { fn(ds); } catch (e) { console.error(e); } } }
  function reset() { use(builtin()); }
  function subscribe(fn) { subs.add(fn); return () => subs.delete(fn); }

  function venue(name, ds) { return (ds || activeDs()).venues.find((v) => v.venue === name) || null; }
  function venues(ds) { return (ds || activeDs()).venues.map((v) => v.venue); }

  /** An OBZ.engine.Snapshot for a venue. Phoenix uses the raw (unaggregated) orders when
   *  the built-in raw snapshot matches the venue's fetch time. */
  function snapshot(name, ds) {
    const d = ds || activeDs();
    const key = d.label + "|" + name;
    if (snapCache.has(key)) return snapCache.get(key);
    const v = venue(name, d);
    if (!v) return null;
    let snap;
    const raw = d.phoenixRaw && d.phoenixRaw.snapshot;
    if (name === "phoenix" && raw && Math.abs(Number(raw.fetched_at) - v.fetchedAt) < 1) snap = OBZ.engine.Snapshot.fromDict(raw);
    else snap = OBZ.engine.Snapshot.fromUsdLevels({ venue: v.venue, symbol: v.symbol, fetched_at: v.fetchedAt, bids: v.bids, asks: v.asks, meta: v.meta });
    snapCache.set(key, snap);
    return snap;
  }
  function book(name, opts) { const s = snapshot(name); return s ? s.toBook(opts) : null; }
  function phoenix() { const p = activeDs().phoenixRaw || builtin().phoenixRaw; return p ? p.summary : null; }

  function label(v) { return LABELS[v] || (v ? v.charAt(0).toUpperCase() + v.slice(1) : ""); }
  function colorVar(v, i) { return COLORS[v] || FALLBACK_COLORS[(i || 0) % FALLBACK_COLORS.length]; }

  OBZ.data = {
    MAX_BYTES, KIND, DEFAULT_FEES, DataError,
    validate, parse, readFile, normalize,
    builtin, active: activeDs, use, reset, subscribe,
    venue, venues, snapshot, book, phoenix, label, colorVar,
    /** The raw payload (tests). */
    _payload: loadPayload,
  };
})(window.OBZ = window.OBZ || {});
